import os
from typing import List, Tuple

import argostranslate.package
import argostranslate.translate
import ctranslate2
import stanza
from tqdm import tqdm

ARGOSPKG = argostranslate.package


os.environ['ARGOS_DEVICE_TYPE'] = 'cuda'
DEVICE = os.environ.get("ARGOS_DEVICE_TYPE", "cpu")  # "cuda" or "cpu"

SOURCE_LANG_CODE_ARGO = "es"
TARGET_LANG_CODE_ARGO = "en"

# Caches
PKG_CACHE: dict[tuple[str, str], ARGOSPKG.Package] = {}
CT2_CACHE: dict[tuple[str, str], ctranslate2.Translator] = {}
STANZA_CACHE: dict[str, stanza.Pipeline] = {}  # keyed by source lang (pipeline只依赖src)

# -----------------------------
# Helpers
# -----------------------------
def build_stanza(src_lang: str, stanza_dir: str) -> stanza.Pipeline:
    """Create or reuse a Stanza tokenizer-only pipeline for src_lang from package's stanza/"""
    pipe = STANZA_CACHE.get(src_lang)
    if pipe is None:
        pipe = stanza.Pipeline(
            lang=src_lang,
            dir=stanza_dir,
            processors="tokenize",
            use_gpu=(DEVICE == "cuda"),
            logging_level="WARNING",
        )
        STANZA_CACHE[src_lang] = pipe
    return pipe

def sbd_with_stanza(pipe: stanza.Pipeline, text: str) -> List[str]:
    doc = pipe(text)
    # 统一抽取句子文本
    out: List[str] = []
    for s in doc.sentences:
        if hasattr(s, "text"):
            val = s.text.strip()
        elif hasattr(s, "tokens"):
            val = "".join([t.text_with_ws for t in s.tokens]).strip()
        else:
            val = ""
        if val:
            out.append(val)
    return out

def get_translator(src: str, dst: str, pkg: ARGOSPKG.Package) -> ctranslate2.Translator:
    """Create or reuse CTranslate2 translator from package_path/model."""
    key = (src, dst)
    tr = CT2_CACHE.get(key)
    if tr is None:
        model_dir = pkg.package_path / "model"
        tr = ctranslate2.Translator(
            str(model_dir),
            device=DEVICE,
            # compute_type=("float16" if DEVICE == "cuda" else "int8"),
            inter_threads=max(2, (os.cpu_count() or 8)//4),
            intra_threads=max(1, (os.cpu_count() or 8)//2),
            max_queued_batches=8,
        )
        CT2_CACHE[key] = tr
    return tr

def get_or_install_package(src: str, dst: str) -> ARGOSPKG.Package:
    """Return Argos package for (src,dst), install if missing."""
    if (src, dst) in PKG_CACHE:
        return PKG_CACHE[(src, dst)]
    # 先尝试已安装
    for P in ARGOSPKG.get_installed_packages():
        if P.from_code == src and P.to_code == dst:
            PKG_CACHE[(src, dst)] = P
            return P
    # 不在本地则安装
    ARGOSPKG.update_package_index()
    for cand in ARGOSPKG.get_available_packages():
        if cand.from_code == src and cand.to_code == dst:
            print("install", cand)
            cand.install()
            break
    # 再次检索已安装
    for P in ARGOSPKG.get_installed_packages():
        if P.from_code == src and P.to_code == dst:
            PKG_CACHE[(src, dst)] = P
            return P
    raise RuntimeError(f"Argos package {src}->{dst} not found after install.")

INSTALLED_TRANSLATORS = {}

def get_or_install_translator(_from, _to):
    """获取或安装并加载一个Argos Translate翻译器"""
    if tr := INSTALLED_TRANSLATORS.get((_from, _to)):
        return tr

    try:
        tr = argostranslate.translate.get_translation_from_codes(_from, _to)
        INSTALLED_TRANSLATORS[(_from, _to)] = tr
        print(f"Loaded existing translator: {_from} -> {_to}")
        return tr
    except Exception:
        print(f"Translator for {_from} -> {_to} not found. Attempting to install...")

    argostranslate.package.update_package_index()
    available_packages = argostranslate.package.get_available_packages()
    
    package_to_install = next(
        filter(lambda x: x.from_code == _from and x.to_code == _to, available_packages), 
        None
    )
    
    if package_to_install:
        print(f"Installing package: {package_to_install}")
        package_to_install.install()
        # 重新加载
        tr = argostranslate.translate.get_translation_from_codes(_from, _to)
        INSTALLED_TRANSLATORS[(_from, _to)] = tr
        print(f"Successfully installed and loaded: {_from} -> {_to}")
        return tr
    else:
        raise RuntimeError(f"Could not find a translation package for {_from} -> {_to}")
